python3 - <<'EOF'
import dataclasses, hashlib, hmac, json
from nearproof import (cert, locate_cert, revoke_trust, TrustRevocation,
                       VerifierTrust, attest_observation_for_point, RangeDecision)

ROOT = b"\x09" * 32
KEY_A = b"\xaa" * 32

# build one trust + record set reusing test geometry helpers minimally
def rec(ident, x, y, key, ub=5.0, point=(0.0,0.0), ctx="room-7"):
    return attest_observation_for_point(ident, x, y, RangeDecision(1, ub, True), point, ctx, 0.0, key)

ta = cert("a", 3.0, 0.0, KEY_A, ROOT)
tb = cert("b", 0.0, 4.0, b"\xbb"*32, ROOT)
tc = cert("c", 0.0, 0.0, b"\xcc"*32, ROOT)
trusts = [ta, tb, tc]
records = [rec("a",3.0,0.0,KEY_A), rec("b",0.0,4.0,b"\xbb"*32), rec("c",0.0,0.0,b"\xcc"*32, ub=0.0)]

# default unchanged
c = locate_cert(records, (0.0,0.0), "room-7", trusts, ROOT)
print("baseline", c)

# revocation round-trip + mac formula
rv = revoke_trust(ta, ROOT)
assert isinstance(rv, TrustRevocation)
assert rv.target == ta.mac and len(rv.target) == 32 and len(rv.mac) == 32
payload = {"version":1,"id":"a","target":ta.mac.hex()}
enc = json.dumps(payload, separators=(",",":")).encode()
assert rv.mac == hmac.new(ROOT, b"NPVR1"+enc, hashlib.sha256).digest()
assert TrustRevocation.from_bytes(rv.to_bytes()) == rv
assert rv == TrustRevocation(1, "a", ta.mac, rv.mac)
try:
    rv.version = 2
except dataclasses.FrozenInstanceError:
    pass
print("revocation encoding/mac ok")

# matched cert -> ValueError
try:
    locate_cert(records, (0.0,0.0), "room-7", trusts, ROOT, revocations=[rv])
    print("ERROR: should have raised")
except ValueError as e:
    print("revoked cert rejected:", e)

# bytes mixing
try:
    locate_cert(records, (0.0,0.0), "room-7", trusts, ROOT, revocations=[rv.to_bytes()])
    print("ERROR: bytes form should raise")
except ValueError:
    print("bytes-form revocation ok")

# unmatched id -> ValueError
rvx = revoke_trust(cert("z", 1.0, 1.0, b"\x77"*32, ROOT), ROOT)
try:
    locate_cert(records, (0.0,0.0), "room-7", trusts, ROOT, revocations=[rvx])
    print("ERROR: unmatched id must raise")
except ValueError as e:
    print("unmatched id rejected:", e)

# target mismatch (old revoked cert mac under same id) -> ValueError
old_a = cert("a", 3.0, 0.0, KEY_A, b"\x01"*32)  # signed by other root; mac differs
old_rv = revoke_trust(old_a, ROOT)  # mac won't verify under ROOT... build valid-bad target instead
# craft revocation with valid root mac but target != presented cert mac
rec_bad = TrustRevocation(version=1, id="a", target=b"\x12"*32, mac=b"\x00"*32)
from nearproof import _trust_revocation_mac, _trust_revocation_payload
from dataclasses import replace
rec_bad = replace(rec_bad, mac=_trust_revocation_mac(ROOT, _trust_revocation_payload(rec_bad)))
try:
    locate_cert(records, (0.0,0.0), "room-7", trusts, ROOT, revocations=[rec_bad])
    print("ERROR: unmatched target must raise")
except ValueError as e:
    print("unmatched target rejected:", e)

# duplicate revocations -> ValueError
try:
    locate_cert(records, (0.0,0.0), "room-7", trusts, ROOT, revocations=[rv, rv])
    print("ERROR duplicate must raise")
except ValueError as e:
    print("duplicate rejected:", e)

# wrong root mac on revocation
bad_root_rv = revoke_trust(ta, b"\x08"*32)
try:
    locate_cert(records, (0.0,0.0), "room-7", trusts, ROOT, revocations=[bad_root_rv])
    print("ERROR wrong-root revocation must raise")
except ValueError as e:
    print("wrong-root revocation rejected:", e)

# revoking a cert that is not presented (trusts list excludes a) -> ValueError
try:
    locate_cert(records, (0.0,0.0), "room-7", [tb,tc], ROOT, revocations=[rv])
    print("ERROR: record a has no trust anyway; expect missing trust error first")
except ValueError as e:
    print("no-present-cert case rejected:", e)

# TypeError cases
for bad in ("", bytearray(b"x"), None, 7):
    try:
        revoke_trust(ta, bad)
        print("ERROR root", bad)
    except (TypeError, ValueError) as e:
        assert isinstance(bad, bytes) or isinstance(e, TypeError), (bad, e)
try:
    revoke_trust("not a trust", ROOT)
    print("ERROR trust shape")
except TypeError as e:
    print("non-VerifierTrust rejected:", e)
try:
    locate_cert(records, (0.0,0.0), "room-7", trusts, bytearray(ROOT), revocations=None)
    print("ERROR locate root type")
except TypeError as e:
    print("locate_cert non-bytes root rejected:", e)

# constructor type/value splits
TrustRevocation(1, "a", b"\x00"*32, b"\x00"*32)
for bad in ("1", 1.0, True, None):
    try: TrustRevocation(bad, "a", b"\x00"*32, b"\x00"*32)
    except TypeError: pass
    else: print("ERROR version type", bad)
for bad in (1, b"a", None):
    try: TrustRevocation(1, bad, b"\x00"*32, b"\x00"*32)
    except TypeError: pass
    else: print("ERROR id type", bad)
try: TrustRevocation(1, "", b"\x00"*32, b"\x00"*32)
except ValueError: pass
for bad in ("00"*32, None, b"\x00"*31, b"\x00"*33):
    try: TrustRevocation(1, "a", bad, b"\x00"*32)
    except (TypeError, ValueError): pass
    else: print("ERROR target", bad)
# from_bytes type
try: TrustRevocation.from_bytes("x")
except TypeError: pass
# from_bytes does not verify mac
obj = json.loads(rv.to_bytes()); obj["mac"]="00"*32
forged = json.dumps(obj, separators=(",",":")).encode()
d = TrustRevocation.from_bytes(forged)
assert d.mac == b"\x00"*32
print("constructor/from_bytes contracts ok")
EOF

